setup.bench_collision.CollisionPipelineS.code:
class CollisionPipelineSetup:
    def time_construct(self, world_count, broad_phase):
        self.pipeline = newton.CollisionPipeline(self.model, broad_phase=broad_phase)
        wp.synchronize_device(self.model.device)

    def setup(self, world_count, broad_phase):
        world = newton.ModelBuilder()
        for i in range(16):
            body = world.add_body(xform=wp.transform((i * 0.4, 0.0, 0.5), wp.quat_identity()))
            if i % 2:
                world.add_shape_cylinder(body, radius=0.15, half_height=0.3)
            else:
                world.add_shape_box(body, hx=0.15, hy=0.15, hz=0.3)
        builder = newton.ModelBuilder()
        builder.replicate(world, world_count)
        builder.add_ground_plane()
        self.model = builder.finalize()
        # Warm up without keeping the pipeline, so the timed call does not release it.
        newton.CollisionPipeline(self.model, broad_phase=broad_phase)
        gc.collect()
        wp.synchronize_device(self.model.device)

setup.bench_model.FastInitializeModel.ti.code:
class FastInitializeModel:
    @skip_benchmark_if(wp.get_cuda_device_count() == 0)
    def time_initialize_model(self, robot, world_count):
        builder = Example.create_model_builder(robot, world_count, randomize=True, seed=123)

        # finalize model
        _model = builder.finalize()
        wp.synchronize_device()

    def setup_cache(self):
        # Finalize small models first so the asset download and one-time kernel
        # compilation stay out of the timed builds. Warp compiles per device
        # target, so warm both the default device (for time_initialize_model)
        # and CPU (for peakmem_initialize_model_cpu). Fresh builder per
        # finalize: finalize() mutates builder state in place.
        for robot in self.params[0]:
            for device in (None, "cpu"):
                builder = Example.create_model_builder(robot, 1, randomize=False, seed=123)
                model = builder.finalize(device=device)
                del model
                del builder

